<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['guardar']))$pdo->prepare('INSERT INTO postventa_recordatorios(cotizacion_id,tipo,fecha_recordatorio,descripcion,estado) VALUES(?,?,?,?,?)')->execute([(int)$_POST['cotizacion_id'],epost('tipo','Seguimiento'),epost('fecha_recordatorio',date('Y-m-d')),epost('descripcion'), 'Pendiente']);if(isset($_POST['estado']))$pdo->prepare('UPDATE postventa_recordatorios SET estado=? WHERE id=?')->execute([epost('nuevo_estado'),(int)$_POST['id']]);ego('postventa.php');}
$f=$_GET['filtro']??'pendientes';$sql="SELECT pr.*,c.folio,c.cliente,c.telefono,c.vehiculo FROM postventa_recordatorios pr JOIN cotizaciones c ON c.id=pr.cotizacion_id";$args=[];if($f==='pendientes')$sql.=" WHERE pr.estado='Pendiente'";elseif($f==='vencidos')$sql.=" WHERE pr.estado='Pendiente' AND pr.fecha_recordatorio<CURDATE()";$sql.=' ORDER BY pr.fecha_recordatorio,pr.id';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$cots=srnu_get_cotizaciones_select();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Postventa · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1>Seguimiento postventa</h1><p>Garantías, revisiones y recordatorios de servicio.</p></div></div><section class="panel" style="padding:18px"><form method="post" class="erp-form cols-4"><select name="cotizacion_id" required><option value="">Cotización / cliente</option><?php foreach($cots as $c):?><option value="<?=$c['id']?>"><?=eh(srnu_cotizacion_label($c))?></option><?php endforeach;?></select><select name="tipo"><option>Seguimiento</option><option>Revisión</option><option>Garantía</option><option>Mantenimiento</option><option>Renovación de protección</option></select><input type="date" name="fecha_recordatorio" value="<?=date('Y-m-d',strtotime('+6 months'))?>"><input name="descripcion" required placeholder="Qué debemos recordar"><button class="btn blue" name="guardar" value="1">Crear recordatorio</button></form></section><div class="toolbar" style="margin:16px 0"><a class="btn <?=$f==='pendientes'?'blue':'light'?>" href="?filtro=pendientes">Pendientes</a><a class="btn <?=$f==='vencidos'?'blue':'light'?>" href="?filtro=vencidos">Vencidos</a><a class="btn <?=$f==='todos'?'blue':'light'?>" href="?filtro=todos">Todos</a></div><section class="tablebox"><table><thead><tr><th>Fecha</th><th>Cliente / vehículo</th><th>Tipo</th><th>Recordatorio</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$late=$r['estado']==='Pendiente'&&$r['fecha_recordatorio']<date('Y-m-d');?><tr class="<?=$late?'stock-low':''?>"><td><?=edate($r['fecha_recordatorio'])?></td><td><b><?=eh($r['cliente'])?></b><div class="muted"><?=eh($r['vehiculo'])?> · <?=eh($r['telefono'])?></div></td><td><?=eh($r['tipo'])?></td><td><?=eh($r['descripcion'])?></td><td><span class="badge <?=$r['estado']==='Pendiente'?($late?'badge-red':'badge-orange'):'badge-green'?>"><?=eh($r['estado'])?></span></td><td><form method="post" class="toolbar"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="nuevo_estado"><option>Pendiente</option><option>Completado</option><option>Cancelado</option></select><button class="btn" name="estado" value="1">Actualizar</button><a class="btn green" target="_blank" href="https://wa.me/52<?=preg_replace('/\D+/','',$r['telefono'])?>">WhatsApp</a></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
